
create table if not exists finder.plan_fac(code text primary key, name text, rx text, areas text[], ord int);
create table if not exists finder.plan_area(code text primary key, label text, ord int);
create table if not exists finder.plan_slot(k text primary key, area text, label text, q text, scope text, ord int);
create table if not exists finder.plan_cand(k text, sku text, pos int, score real, primary key(k,sku));
create table if not exists finder.plan_pick(fac text, k text, rn int, sku text, primary key(fac,k,rn));
create table if not exists finder.plan_map(id int primary key default 1, data jsonb, updated_at timestamptz default now());
alter table finder.plan_fac enable row level security; alter table finder.plan_area enable row level security;
alter table finder.plan_slot enable row level security; alter table finder.plan_cand enable row level security;
alter table finder.plan_pick enable row level security; alter table finder.plan_map enable row level security;
delete from finder.plan_fac; delete from finder.plan_area; delete from finder.plan_slot;
